# -*- coding: utf-8 -*-
"""
小学适龄教学诊断反馈表（与病例对齐表 RV_FEEDBACK 并列生成；每条严格绑定题库中的 (key, 干扰选项)）。
用于填补概念题、构式题与时态镜头题等「无现成错句病例对应，但孩子选错时最需要点拨」的题面。
"""

PEDAGOGIC_FEEDBACK = {
    # --- V / C 高频用法辨析 ---
    ("LQ:V-43:0", "cause"): {"why": "cause 常用来带坏结果（cause trouble / cause an accident）；「带来进步」这种好消息用 bring about 才地道。", "ref": "V-43 规律要点"},
    ("LQ:V-43:0", "两个一样"): {"why": "两个词冷暖色彩不同：cause 偏负面「惹出麻烦」，bring about 偏中性/积极「促成、带来进步」。", "ref": "V-43 规律要点"},
    ("LQ:V-44:0", "there"): {"why": "there 是「在那里」（比如 over there），不是「他们的」。需要形容词性物主代词 their。", "ref": "V-44 同音词辨析"},
    ("LQ:V-44:0", "they're"): {"why": "they're 是 they are（他们是）的缩写，后面不能直接当「他们的书」用。这里用 their。", "ref": "V-44 同音词辨析"},
    ("LQ:C-06:0", "the dog（就是那一只）"): {"why": "第一次向朋友提起「我养了一只狗」时，对方还不知道是哪一只，只能先报类别，用 a dog。", "ref": "C-06 规律要点"},
    ("LQ:C-11:0", "去当小学生上学"): {"why": "go to school（无 the）才是「去上学」；加了 the（go to the school）是去那栋楼办事，不是去上课。", "ref": "C-11 规律要点"},
    ("LQ:C-11:0", "去睡觉"): {"why": "the school 指「那所学校」建筑；爸爸去学校不是去睡觉，而是去那所学校办事或接人。", "ref": "C-11 规律要点"},
    ("LQ:C-15:0", "an advice"): {"why": "advice 在英语里是不可数名词（看作一摊建议），不能直接加 an；要借助量词 a piece of。", "ref": "C-15 规律要点"},
    ("LQ:C-15:0", "advices"): {"why": "不可数名词 advice 不能在词尾加 -s；数「一条建议」要说 a piece of advice。", "ref": "C-15 规律要点"},
    ("LQ:C-16:0", "are（看成几口人）"): {"why": "紧挨着 big 形容家庭规模「很大」时，把 family 看作一个整体，动词首选单数 is。", "ref": "C-16 规律要点"},
    ("LQ:C-16:0", "两个都不行"): {"why": "family 指「整个家」时配 is（My family is big.），指「家人们都在」时才配 are；这里主读法用 is。", "ref": "C-16 规律要点"},

    # --- PR 代词核心 ---
    ("LQ:PR-01:0", "代替老师的名字"): {"why": "we 指「我们（包含说话人和听话人）」，不是单纯替老师一个人的名字。", "ref": "PR-01 规律要点"},
    ("LQ:PR-01:0", "表示人数很多"): {"why": "只要两个人就能用 we！老师说 We are a team 重点是把大家拉进同一个团队。", "ref": "PR-01 规律要点"},
    ("LQ:PR-02:0", "一样，都指老师"): {"why": "I 就像接力棒：谁拿到话筒说 I，I 就变成谁——你说 I 时就指你自己，不再指老师。", "ref": "PR-02 规律要点"},
    ("LQ:PR-02:0", "一样，都指你"): {"why": "老师说 I am happy 时指的是老师自己，你说时才指你——I 永远跟着当前说话的人走。", "ref": "PR-02 规律要点"},
    ("LQ:PR-03:0", "不包括"): {"why": "老师面向全班说「今天我们有英语课」，是老师和同学们一起上，所以包括你在内。", "ref": "PR-03 规律要点"},
    ("LQ:PR-03:0", "英语的 we 从不包括听者"): {"why": "恰恰相反，日常课堂或邀请（Let's go / We have English）里的 we 经常把听话人算进来。", "ref": "PR-03 规律要点"},
    ("LQ:PR-04:0", "把 you 换成 thou"): {"why": "现代英语早就统一只用 you 啦，不再靠 thou 区分礼貌——礼貌主要靠加称呼、please 或 Could you。", "ref": "PR-04 规律要点"},
    ("LQ:PR-04:0", "不说话"): {"why": "向老师求助或打招呼还是要大声说出来的！加上 Miss/Mr、please 或 Could you 就很有礼貌啦。", "ref": "PR-04 规律要点"},
    ("LQ:PR-05:0", "每个格子都有"): {"why": "英语的 I / you / we / they 都不分男女，只有「他/她/它」（he / she / it）这一格才分。", "ref": "PR-05 规律要点"},
    ("LQ:PR-05:0", "只有第一人称有"): {"why": "第一人称 I / we 不分性别；性别标记只在第三人称单数（he / she）里出现。", "ref": "PR-05 规律要点"},
    ("LQ:PR-06:0", "happy 用错了"): {"why": "happy 放在 is 后面作表语没问题；真正的问题是前面有两个男生 Tom 和 Jack，后面的 He 不知道在说谁。", "ref": "PR-06 规律要点"},
    ("LQ:PR-06:0", "没有问题"): {"why": "前面刚点名 Tom 和 Jack 两个男生，紧接着只说 He，读者会犯晕：到底谁开心？该直接说出名字。", "ref": "PR-06 规律要点"},
    ("LQ:PR-08:0", "补 the"): {"why": "the 不能当主语站在动词前面。「下雨了」必须找个替补主语 It 占住最前面的位子：It is raining。", "ref": "PR-08 规律要点"},
    ("LQ:PR-08:0", "什么都不用补"): {"why": "英语句子的主语位子绝不能空着（不像中文可以说「下雨了」），必须请 It 来占主语位置。", "ref": "PR-08 规律要点"},
    ("LQ:PR-11:0", "罚抄 he/she 各十遍"): {"why": "抄写时通常有时间慢慢想，所以写不常错；说的时候抢时间才容易嘴瓢，需要在限时开口里多练。", "ref": "PR-11 规律要点"},
    ("LQ:PR-11:0", "背性别单词表"): {"why": "he/she 的中文意思你早就背会了，错的是「张嘴一瞬间挑错词」，要练快速口头反应。", "ref": "PR-11 规律要点"},

    # --- CO 构式小剧场 ---
    ("LQ:CO-01:3", "He baked a cake."): {"why": "He baked a cake. 里只写了他烤了一个蛋糕，没有写烤给谁；加进 her 变成双宾句型后才有人收到。", "ref": "CO-01 规律要点"},
    ("LQ:CO-01:3", "两句都有"): {"why": "第一句只是主谓宾（烤了蛋糕），没有收件人；只有双宾句 He baked her a cake. 才多出了「给她」。", "ref": "CO-01 规律要点"},
    ("LQ:CO-03:1", "Explain me this. 里的 explain"): {"why": "explain 不进双宾「人 + 物」的模具，不能说 explain me this，要说 explain this to me。", "ref": "CO-03 规律要点"},
    ("LQ:CO-03:1", "They donated us books. 里的 donate"): {"why": "donate（捐赠）也不进双宾模具，不能说 donate us books，要说 donate books to us。", "ref": "CO-03 规律要点"},
    ("LQ:CO-04:0", "He kicked the ball over the fence."): {"why": "kick（踢）本身就能造成物体位移，「把球踢过栅栏」完全合乎致使移动模具！进不去的是 know（知道）。", "ref": "CO-04 规律要点"},
    ("LQ:CO-04:0", "Sam sneezed the napkin off the table."): {"why": "这是语言学经典的创意用法：打喷嚏真的可以把餐巾纸吹下桌子！know（知道）这种静态心理动词才推不动东西。", "ref": "CO-04 规律要点"},
    ("LQ:CO-05:3", "They painted the door."): {"why": "They painted the door. 只说了「刷门」这个动作，没有写出结果（比如刷成红色 red）。", "ref": "CO-05 规律要点"},
    ("LQ:CO-05:3", "They like the red door."): {"why": "这里的 red 只在名词前当普通定语，没有表现「把门刷得变红」这个动作结果。", "ref": "CO-05 规律要点"},
    ("LQ:CO-06:0", "已经到手了"): {"why": "promised 是「口头答应给」，目前孩子心里还在盼着，自行车还没真的交到手里。", "ref": "CO-06 规律要点"},
    ("LQ:CO-06:0", "永远不会给了"): {"why": "promise 表示认真许诺将要给，虽然还没到手，但未来有盼头，不是拒绝。", "ref": "CO-06 规律要点"},
    ("LQ:CO-08:3", "Mum made the cake."): {"why": "Mum made the cake. 还是主动句，主角仍是做事的 Mum；只有被动句里才会出现 by Mum。", "ref": "CO-08 规律要点"},
    ("LQ:CO-08:3", "The cake is on the table."): {"why": "这句只描述蛋糕在哪里，根本没有提到做蛋糕的人。", "ref": "CO-08 规律要点"},
    ("LQ:CO-14:2", "going"): {"why": "want 点名只找不定式 to do 当搭档（I want to go），不能直接接 -ing。", "ref": "CO-14 规律要点"},
    ("LQ:CO-14:2", "go"): {"why": "want 后面不能直接光着跟动词原形 go，中间一定要架一座 to 桥：I want to go。", "ref": "CO-14 规律要点"},

    # --- QI 疑问与语序 ---
    ("LQ:QI-01:0", "地方——派 where"): {"why": "where 专门问地点「在哪里」；问「生日是哪天（时间）」要派 when。", "ref": "QI-01 规律要点"},
    ("LQ:QI-01:0", "人——派 who"): {"why": "who 专门问「是谁」；问生日在哪一天是在找时间，要派 when。", "ref": "QI-01 规律要点"},
    ("LQ:QI-01:2", "地方"): {"why": "Who 问的是人物身份（「谁」），不是地点（「哪里」）。回答 Who is your teacher? 要说出老师的名字或身份。", "ref": "QI-01 规律要点"},
    ("LQ:QI-01:2", "原因"): {"why": "问原因才用 Why，Who 问的是「谁（人）」。", "ref": "QI-01 规律要点"},
    ("LQ:QI-03:2", "why"): {"why": "why 是问「为什么」的副词，不是「谁的」。「谁的」对应 whose。", "ref": "QI-03 规律要点"},
    ("LQ:QI-03:2", "who"): {"why": "who 相当于主格 he（「谁」）；表示「谁的（东西）」必须换成所有格 whose。", "ref": "QI-03 规律要点"},
    ("LQ:QI-09:0", "To get some books."): {"why": "Why are you wet? 问的是已经湿了的原因（因为下雨了），不是去做某事的目的（为了去借书）。", "ref": "QI-09 规律要点"},
    ("LQ:QI-09:0", "Yes, I am."): {"why": "带 Why 的特殊疑问句不能只答 Yes/No，要回答出原因。", "ref": "QI-09 规律要点"},
    ("LQ:QI-09:1", "Because get some books."): {"why": "Because 后面要接完整的「主语 + 动词」句子，不能光秃秃接动词 get；表目的直接用 To get some books. 最地道。", "ref": "QI-09 规律要点"},
    ("LQ:QI-09:1", "Why books."): {"why": "Why 是用来提问「为什么」的，不能直接拿来当答案。", "ref": "QI-09 规律要点"},
    ("LQ:QI-10:2", "How"): {"why": "How 多用来问「怎么样 / 方式 / 程度」；问「那是什么东西」要用 What。", "ref": "QI-10 规律要点"},
    ("LQ:QI-10:2", "When"): {"why": "When 专门问「什么时候」；问事物名称要用 What。", "ref": "QI-10 规律要点"},
    ("LQ:QI-12:0", "Yes.（意思是「对，我不喜欢」）"): {"why": "英语看的是「后面的事实是肯定还是否定」：只要事实是「我不喜欢」，不管问句带不带 n't，一律用 No, I don't.！", "ref": "QI-12 规律要点"},
    ("LQ:QI-12:0", "Yes, I do."): {"why": "Yes, I do. 的意思是「不，我喜欢！」；既然你不喜欢，必须选 No, I don't.。", "ref": "QI-12 规律要点"},
    ("LQ:QI-12:1", "No, I don't."): {"why": "No, I don't. 表示「我不喜欢」。既然你其实很喜欢，英语只看肯定事实，答 Yes, I do.。", "ref": "QI-12 规律要点"},
    ("LQ:QI-12:1", "No.（意思是「对，我喜欢」）"): {"why": "别被中文翻译带偏了！英语用 Yes 配肯定事实（Yes, I do. = 我喜欢），不能用 No 接肯定事实。", "ref": "QI-12 规律要点"},

    # --- E / W 语用与写作 ---
    ("LQ:E-01:0", "只是在报告天气"): {"why": "屋里说 It's cold here. 表面在陈述冷，弦外之音常常是委婉请人关窗或调高温度。", "ref": "E-01 规律要点"},
    ("LQ:E-01:0", "在背课文"): {"why": "说话常带着目的，同学说冷往往是想让身边的人帮忙关上窗户。", "ref": "E-01 规律要点"},
    ("LQ:E-02:0", "答 Yes, I can 然后坐着不动"): {"why": "Can you open the window? 不是在测你的力气，是礼貌请求帮忙，所以光嘴上答 Yes 不去开门会显得奇怪。", "ref": "E-02 规律要点"},
    ("LQ:E-02:0", "答 No, I can't"): {"why": "没有特殊原因却直接拒绝老师的请求不得体；起身去把窗打开才是顺理成章的回应。", "ref": "E-02 规律要点"},
    ("LQ:W-14:0", "although"): {"why": "although 表示转折「虽然」，但摔倒和哭起来是顺着时间发生的因果连贯，用 then（然后/接着）。", "ref": "W-14 规律要点"},
    ("LQ:W-14:0", "moreover"): {"why": "moreover 是书面语「此外/而且」，通常用于议论文补充论点，不适合讲「摔倒后哭了」的小故事。", "ref": "W-14 规律要点"},

    # --- TA 时态站 50 道未对齐选择题（覆盖 TA01..TA18 全站！）---
    ("TA:TA01-E1", "We played football in the afternoon."): {"why": "played 把整场球从头到尾打包看完了；题目要你钻进「正踢到一半」的画面，所以得用 were playing。", "ref": "TA-01 开关组合"},
    ("TA:TA01-E1", "We play football in the afternoon."): {"why": "play 是一般现在时（讲日常习惯），但这道题明确说的是「昨天下午」的过去进行画面。", "ref": "TA-01 开关组合"},
    ("TA:TA01-E3", "I finished my homework."): {"why": "妈妈问的是「现在能不能出去玩」，强调「此刻作业已经好了」的结果，完成时 have finished 比单讲过去 finished 更贴合。", "ref": "TA-01 开关组合"},
    ("TA:TA01-E3", "I finish my homework every day."): {"why": "every day 说的是每天习惯，没回答妈妈「现在这一份做完了没有」。", "ref": "TA-01 开关组合"},
    ("TA:TA01-E4", "He read a picture book."): {"why": "你正站在窗边看他读到一半还没完——这是此刻正在进行的画面，要用 is reading。", "ref": "TA-01 开关组合"},
    ("TA:TA01-E4", "He reads a picture book at school."): {"why": "reads 讲的是平时的习惯，不是眼前窗口里「正在读到一半」的画面。", "ref": "TA-01 开关组合"},
    ("TA:TA02-E4", "It rained a lot."): {"why": "rained 是过去式，讲以前下过雨；题干说天正乌云密布，雨还没下下来呢！", "ref": "TA-02 预兆将来"},
    ("TA:TA02-E4", "It rains in spring."): {"why": "rains 讲春天一贯的气候规律，不是眼前乌云压顶马上要下的这阵雨。", "ref": "TA-02 预兆将来"},
    ("TA:TA03-E1", "They were building a house."): {"why": "were building 是镜头推近只看中间「正在盖」；题目要求站在远处「从无到有整件事一次看完」，选 built。", "ref": "TA-03 全景与进行"},
    ("TA:TA03-E2", "They built a house."): {"why": "built 是远处看全景、整座房子盖好收尾；题目让你推近镜头只看中间「正在盖」的过程，选 were building。", "ref": "TA-03 全景与进行"},
    ("TA:TA03-E4", "He ran to the playground and stopped."): {"why": "这句写成了「跑到操场并且停下」的完整结尾；题目说「还没停下来、画面冻在中间」，要用 was running。", "ref": "TA-03 过程镜头"},
    ("TA:TA03-E4", "He runs every morning."): {"why": "every morning 是天天跑步的习惯，不是推开门那一瞬看见「正跑在中间」的定格画面。", "ref": "TA-03 过程镜头"},
    ("TA:TA03-E5", "把镜头推近，只看中间一段"): {"why": "如果只看中间一段，动词得变成 were building；只用 built 是从头看到尾的全景看法。", "ref": "TA-03 全景视角"},
    ("TA:TA03-E5", "站在现在看过去的痕迹"): {"why": "看现在痕迹的是完成时 have built，而 built 是普通全景过去时。", "ref": "TA-03 全景视角"},
    ("TA:TA04-E1", "I eat now."): {"why": "说话的「现在」只有一眨眼那么短，整顿饭吃不进一眨眼——正在吃必须钻进镜头里，用 I am eating now。", "ref": "TA-04 进行时"},
    ("TA:TA04-E2", "I am getting up at seven now."): {"why": "「每天七点起床」是天天重复的作息习惯，正职属于一般现在时 get up，不该用正在进行。", "ref": "TA-04 习惯本职"},
    ("TA:TA04-E3", "They play football."): {"why": "前面老师都喊 Look!（快看眼前！）了，说明事情正在发生，要用进行时 are playing football。", "ref": "TA-04 正在发生"},
    ("TA:TA04-E5", "讲一件正在发生的事"): {"why": "讲正在发生需要 is getting up；单用 get up + every day 专职讲天天重复的习惯。", "ref": "TA-04 习惯本职"},
    ("TA:TA04-E5", "讲昨天发生的事"): {"why": "昨天发生的事会用过去式 got up，every day 讲的是平时习惯。", "ref": "TA-04 习惯本职"},
    ("TA:TA05-E2", "I lose my key."): {"why": "lose 是一般现在时，变成「我平时经常丢钥匙」；现在站在门外进不去是因为刚才丢了、结果还在，选 I have lost my key。", "ref": "TA-05 现时结果"},
    ("TA:TA05-E2", "I lost my key at school this morning."): {"why": "带了 this morning 虽然合语法，但题目让你盯着「现在进不了门的结果」，且不带过去时间点，选完成时最精准。", "ref": "TA-05 现时结果"},
    ("TA:TA05-E5", "I go to Beijing."): {"why": "go 讲平时常去北京或习惯；要表达「我去过北京，这份经历就在我身上」必须用 I have been to Beijing。", "ref": "TA-05 经历用法"},
    ("TA:TA05-E5", "I am going to Beijing."): {"why": "am going to 表示「打算/正在去」北京，还没到过呢；去过了、有照片为证用 have been to。", "ref": "TA-05 经历用法"},
    ("TA:TA06-E6", "I saw him at three o'clock."): {"why": "题干明确说「不给任何时间词，只报现在这条新鲜消息」——一点出 at three o'clock 就钉死在过去，不是单纯报现在结果了。", "ref": "TA-06 不锚定过去"},
    ("TA:TA06-E6", "I see him every day."): {"why": "see him every day 是每天经常见面，不是刚才见到他并高兴报信。", "ref": "TA-06 不锚定过去"},
    ("TA:TA07-E1", "The children run in the park."): {"why": "run 是能一直跑下去的活动（动态过程），不是一动不动的静止状态。", "ref": "TA-07 动词形状"},
    ("TA:TA07-E1", "He found his key."): {"why": "found（找到）是「啪」一瞬间发生的变化，不是静止不变的状态；know（知道）才是静态牌子。", "ref": "TA-07 动词形状"},
    ("TA:TA07-E2", "能一直转的轮子（没有终点）"): {"why": "光说 paint（画画）没有终点；一旦变成 painted a picture（画成一幅画），画完就是终点！", "ref": "TA-07 完结型"},
    ("TA:TA07-E2", "啪的一下（瞬间）"): {"why": "画好一幅画需要一笔一笔慢慢完成，不是一秒钟啪的一下就能结束的。", "ref": "TA-07 完结型"},
    ("TA:TA07-E4", "He found his key."): {"why": "「找到钥匙」是眼睛看到的那一瞬间就完成了，不可能持续「找到一小时」。", "ref": "TA-07 持续测试"},
    ("TA:TA07-E5", "能，瞬间的事也有很长的中间一段"): {"why": "「找到」是啪的一刹那：还没找到之前都不叫 found，一找到就结束了，没有中间过程可看。", "ref": "TA-07 瞬间限制"},
    ("TA:TA08-E1", "I wonder if you could help me."): {"why": "两句都礼貌，但 wondered 借用过去形把请求「推远」一步，给老师留出更多余地，语气更柔和。", "ref": "TA-08 礼貌推远"},
    ("TA:TA08-E2", "在讲昨天的事"): {"why": "如果是我「变成你」，现实中昨天也不可能发生！这里用 were 是虚拟语气「推到假如的世界」。", "ref": "TA-08 假设推远"},
    ("TA:TA08-E2", "在说我真的变成了你"): {"why": "既然是 If（假如），就是明确告诉对方「其实我不是你」，所以特意用 were 与现实拉开距离。", "ref": "TA-08 假设推远"},
    ("TA:TA08-E5", "She has a red bag."): {"why": "has 是一般现在时，里面根本没有过去形动词。", "ref": "TA-08 转述后退"},
    ("TA:TA08-E5", "We play games after school."): {"why": "play 是一般现在时，也没有借过去形来做推远动作。", "ref": "TA-08 转述后退"},
    ("TA:TA09-E5", "My brother eats dinner when I get home."): {"why": "题目讲的是过去故事里「我到家之前他就已经吃完了」，用一般现在时 eats/get 变成了每天规律。", "ref": "TA-09 过去的过去"},
    ("TA:TA09-E5", "My brother will eat dinner when I get home."): {"why": "will eat 是还没吃、打算以后吃；题目明确说「我到家时他已经吃完了」。", "ref": "TA-09 过去的过去"},
    ("TA:TA10-E1", "I am going to get the door after lunch."): {"why": "门铃正响着呢，不可能等午饭后再去开！going to 留给提前计划，当场脱口而出用 I'll。", "ref": "TA-10 当场决定"},
    ("TA:TA10-E1", "I get the door every morning."): {"why": "门铃突然响起是当场反应，不是每天早上的固定习惯。", "ref": "TA-10 当场决定"},
    ("TA:TA10-E2", "It rains tomorrow."): {"why": "明天天气不是火车时刻表上印死的事实，不能裸用现在时说 It rains tomorrow；要用 It will rain tomorrow。", "ref": "TA-10 天气预测"},
    ("TA:TA10-E2", "It is raining tomorrow morning at six on the timetable."): {"why": "下雨没法写进人类排的日程时刻表里，也没法事先安排进行时，天气预测还是要用 will。", "ref": "TA-10 天气预测"},
    ("TA:TA10-E4", "I helped you."): {"why": "helped 是「我已经帮过你了」，但朋友现在才刚抱着书晃过来！当场乐意帮忙说 I will help you!。", "ref": "TA-10 当场意愿"},
    ("TA:TA10-E4", "I help you every day."): {"why": "every day 是讲习惯，不是现在马上伸手帮忙那句话。", "ref": "TA-10 当场意愿"},
    ("TA:TA10-E5", "人已经在路上了"): {"why": "「已经在路上 / 苗头已现」是 be going to 的画面感；will 重点是我嘴上「我乐意、我答应」。", "ref": "TA-10 口气对比"},
    ("TA:TA10-E5", "时刻表上定死的"): {"why": "「时刻表上定死的」多用一般现在时（如 The train leaves at six）；I will help you 是主动承诺。", "ref": "TA-10 口气对比"},
    ("TA:TA11-E1", "It will rain next month."): {"why": "乌云已经在头顶压着啦，是眼前的预兆（马上就要下），用 is going to rain 比「下个月才下」贴切得多。", "ref": "TA-11 预兆将来"},
    ("TA:TA11-E1", "It rained yesterday."): {"why": "乌云压顶、风刚刮起，说的是紧接着马上要发生的事，不是昨天。", "ref": "TA-11 预兆将来"},
    ("TA:TA11-E2", "We visited Grandma this weekend."): {"why": "车票刚买好、周末还没到呢！visited 是已经去过了。", "ref": "TA-11 预先计划"},
    ("TA:TA11-E2", "We visit Grandma on Sundays."): {"why": "题干说「这个周末早就买好票定好了计划」，强调提前定好的计划用 are going to visit。", "ref": "TA-11 预先计划"},
    ("TA:TA11-E4", "He catches the train at six."): {"why": "他此刻正攥着票往车站赶，说的不是每天六点坐车的习惯，而是眼前正在奔赴的目标。", "ref": "TA-11 目的在途"},
    ("TA:TA11-E4", "He caught the train."): {"why": "caught 表示已经赶上车了，但题干说他还在去车站的路上！", "ref": "TA-11 目的在途"},
    ("TA:TA11-E5", "乌云压顶，眼看要下雨"): {"why": "「眼前已经有预兆」正是 be going to 的原型场景，不是当场答应的 will。", "ref": "TA-11 场景辨析"},
    ("TA:TA11-E5", "暑假计划一个月前就排好了"): {"why": "早就做好的计划也是 be going to 的地盘；只有「门铃响、当场起身」才是 will 的原型活儿。", "ref": "TA-11 场景辨析"},
    ("TA:TA12-E2", "我写信这件事做过了"): {"why": "现代 I have written the letter 才看重「写过了这件事」；老式语序 the letter written 重心还在「手里那封写好的信」。", "ref": "TA-12 完成时源流"},
    ("TA:TA12-E2", "写信的那个人"): {"why": "written 放在 the letter 后面作定语，修饰的是「那封信」。", "ref": "TA-12 完成时源流"},
    ("TA:TA12-E3", "信还在不在手里"): {"why": "现代完成时已经从「持有物件」滑到「动作已完成的结果与经历」，重点不再看东西是不是还攥在手里。", "ref": "TA-12 完成时源流"},
    ("TA:TA12-E3", "信写得好不好"): {"why": "完成时关注的是「写了没、和现在有啥关系」，不评价文笔好不好。", "ref": "TA-12 完成时源流"},
    ("TA:TA12-E4", "wrote"): {"why": "wrote 是过去式，只能单站在主语后面（I wrote）；跟在助动词 have 后面必须用过去分词 written。", "ref": "TA-12 过去分词"},
    ("TA:TA12-E4", "writing"): {"why": "writing 要跟 be 动词（am writing）配进行时，不能直接放在完成时 have 后面。", "ref": "TA-12 过去分词"},
    ("TA:TA13-E1", "It will rain tomorrow."): {"why": "will rain 是预报推测，不是时刻表安排。", "ref": "TA-13 时刻表现在时"},
    ("TA:TA13-E1", "We are going to visit Grandma."): {"why": "going to 表示个人打算去，不是公共交通时刻表排定的发车时间。", "ref": "TA-13 时刻表现在时"},
    ("TA:TA13-E2", "因为课正在上"): {"why": "时间写明了 tomorrow，所以不是正在上；能用 starts 是因为课程表预先把明天的课定成了既成事实。", "ref": "TA-13 日程现在时"},
    ("TA:TA13-E2", "因为 starts 是过去式"): {"why": "starts 末尾带三单 -s，是不折不扣的一般现在时，不是过去式。", "ref": "TA-13 日程现在时"},
    ("TA:TA13-E3", "The film begins at seven tonight."): {"why": "电影开映时间印在排片表上，完全可以用一般现在时 begins 说今晚的事！不成立的是天气句 *It rains tomorrow。", "ref": "TA-13 范围边界"},
    ("TA:TA13-E3", "Our lesson starts at eight tomorrow."): {"why": "上课时间写在课表上，用 starts 说明天完全正确！不成立的是预报天气句 *It rains tomorrow。", "ref": "TA-13 范围边界"},
    ("TA:TA13-E5", "The film will begin when we are ready."): {"why": "电影院按节目单准点放电影，不会等你准备好才开场；指着墙上节目单说几点开始用 begins。", "ref": "TA-13 排定事实"},
    ("TA:TA13-E5", "The film began at seven."): {"why": "began 是过去已经开场了，但节目单上写的是今晚还没开始的放映时间。", "ref": "TA-13 排定事实"},
    ("TA:TA14-E1", "说错了，过去的故事必须全用过去时"): {"why": "讲故事讲到精彩高潮时，连说书人和英语母语者也爱突然切成现在时，就像现场直播一样有画面感，不是说错。", "ref": "TA-14 历史现在时"},
    ("TA:TA14-E2", "因为 hears 是过去式"): {"why": "hears 是三单现在时，不是过去式！它是讲故事的人为了突出惊险一刻故意切到直播镜头。", "ref": "TA-14 历史现在时"},
    ("TA:TA14-E2", "因为 noise 是单数"): {"why": "hears 用不用 -s 取决于主语 he 是三单，跟宾语 noise 是不是单数没关系。", "ref": "TA-14 历史现在时"},
    ("TA:TA14-E3", "He opened the door yesterday afternoon."): {"why": "用 opened 加上 yesterday afternoon 是平平实实交代过去事件，没有高潮直播感。", "ref": "TA-14 历史现在时"},
    ("TA:TA14-E3", "He opens the door every day at seven."): {"why": "every day at seven 说的是日常作息习惯，不是故事高潮画面。", "ref": "TA-14 历史现在时"},
    ("TA:TA15-E4", "靠猜"): {"why": "英语不用全靠猜——把 yesterday 遮掉，动词 played 屁股后面拖着的 -ed 还在明明白白地喊「这是过去」！", "ref": "TA-15 形态承重"},
    ("TA:TA15-E4", "不知道了，只能再加时间词"): {"why": "汉语才常靠时间词，英语的动词本身会换衣服（play → played），哪怕没时间词也写着「过去」。", "ref": "TA-15 形态承重"},
    ("TA:TA16-E2", "I have lost my key."): {"why": "I have lost my key 讲的是「现在的结果/影响」（进不了门），不是去过某地的经历；「我去过北京」对应 I have been to Beijing。", "ref": "TA-16 经历 vs 结果"},
    ("TA:TA16-E3", "因为「了」就等于完成时"): {"why": "千万别把中文「了」直接画等号给完成时！「昨天丢了钥匙」也有「了」，但一加 yesterday 就得用过去式 lost。", "ref": "TA-16 破除等号"},
    ("TA:TA16-E3", "因为钥匙是昨天丢的"): {"why": "如果特别说出「昨天丢的」，反而不能用 have lost，得换回 I lost my key yesterday。", "ref": "TA-16 破除等号"},
    ("TA:TA17-E1", "go 加上 -ed 推出来的"): {"why": "英语里可没有 *goed！最常用的 go 在变化里独立门户，需要把它的过去式 went 整个记住。", "ref": "TA-17 高频整存"},
    ("TA:TA17-E1", "从 want 变来的"): {"why": "want 的过去式是 wanted，和 went 长得像但完全不是一家——went 是 go 的过去式。", "ref": "TA-17 高频整存"},
    ("TA:TA17-E2", "look"): {"why": "look 的过去式很规矩，是 looked；saw 是 see（看见）的不规则过去式。", "ref": "TA-17 不规则动词"},
    ("TA:TA17-E2", "watch"): {"why": "watch 的过去式也加 -ed（watched）；saw 来自 see。", "ref": "TA-17 不规则动词"},
    ("TA:TA17-E4", "I eat two eggs and drink milk."): {"why": "讲完整个早上发生的过去小故事，却没写时间词，若还用原形 eat/drink 就听不出是过去的事了，必须用 ate / drank。", "ref": "TA-17 形状扛过去"},
    ("TA:TA18-E1", "已经被证明对小学生最有效"): {"why": "说「最有效」就吹过头啦——目前实证主要在青少年和成人上试过，用在小学还只是合理推论。", "ref": "TA-18 证据边界"},
    ("TA:TA18-E1", "背表格一点用都没有"): {"why": "表格能帮你总览全貌，镜头帮着理解怎么挑；方法各有分工，不能一竿子打死。", "ref": "TA-18 证据边界"},
    ("TA:TA18-E2", "镜头讲法完全是编的"): {"why": "镜头讲法是有认知语言学和实验支撑的，问题在于广告把「有希望」夸大成了「一定翻倍」。", "ref": "TA-18 证据边界"},
    ("TA:TA18-E2", "广告里不能画图"): {"why": "问题不在能不能画图，而在于把未在小学生群体验证过的结论说成了「一定」。", "ref": "TA-18 证据边界"},
    ("TA:TA18-E4", "这个讲法保证你一学就会"): {"why": "学习没有「保证一学就会」的魔法，诚实的说法是把已有依据和还需实践检验的地方都说清楚。", "ref": "TA-18 诚实边界"},
    ("TA:TA18-E4", "这个讲法是错的，别学"): {"why": "「在小学生身上待验」不等于「讲法错了」，它有合理的理论和年长组实证基础，值得认真试用。", "ref": "TA-18 诚实边界"},
}
